SELECT t_q.point30, SUM(t_p.point1 * t_q.point1) / SUM(t_q.point1) AS weighted_price FROM (SELECT ts, time_point, company_name, point30, point1 FROM spot_trading_repro.spot_trading_anhui WHERE base_path = 'ods/安徽现货数据/私有/江苏协鑫售电有限公司/日曲线统计/' AND file_path LIKE '%2026-08-01%' AND point31 = '电量') t_q JOIN (SELECT ts, time_point, company_name, point30, point1 FROM spot_trading_repro.spot_trading_anhui WHERE base_path = 'ods/安徽现货数据/私有/江苏协鑫售电有限公司/日曲线统计/' AND file_path LIKE '%2026-08-01%' AND point31 = '电价') t_p ON t_q.ts = t_p.ts AND t_q.company_name = t_p.company_name AND t_q.point30 = t_p.point30 GROUP BY t_q.point30 LIMIT 5;
